#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

bool can_place(int c, vector<int>& positions, int distance) {
    /*
    Returns true if we can place 'c' cows in 'positions' (sorted)
    such that the minimum gap between any two cows is at least 'distance'.
    */
    int count = 1;
    int last_pos = positions[0];
    for (int i = 1; i < positions.size(); i++) {
        if (positions[i] - last_pos >= distance) {
            count++;
            last_pos = positions[i];
            if (count >= c) {
                return true;
            }
        }
    }
    return false;
}

int max_min_distance(vector<int>& positions, int c) {
    /*
    Binary-search the largest minimum distance to place 'c' cows
    in the sorted list 'positions'.
    */
    int left = 0, right = positions[positions.size() - 1] - positions[0];
    int answer = 0;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (can_place(c, positions, mid)) {
            answer = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return answer;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n, c;
        cin >> n >> c;
        vector<int> positions(n);
        for (int i = 0; i < n; i++) {
            cin >> positions[i];
        }
        sort(positions.begin(), positions.end());
        int ans = max_min_distance(positions, c);
        cout << ans << "
";
    }
    return 0;
}
