class Solution {
  public:
    int atMostK(string& s, int k) {
        if (k < 0)
            return 0;

        int i = 0, j = 0, cnt = 0;
        int res = 0;
        int m[26] = {0};

        while (j < s.length()) {
            m[s[j] - 'a']++;
            if (m[s[j] - 'a'] == 1)
                cnt++;

            while (cnt > k) {
                m[s[i] - 'a']--;
                if (m[s[i] - 'a'] == 0)
                    cnt--;
                i++;
            }

            res += (j - i + 1);
            j++;
        }
        return res;
    }

    int countSubstr(string str, int k) { return atMostK(str, k) - atMostK(str, k - 1); }
};
