        if (s.length() != t.length()) return false;

        int arr[26] = {0};

        for (int i = 0 ; i<s.length(); i++){
            arr[s[i]-'a'] += 1;
            arr[t[i] - 'a'] -= 1;
        }

        for (int check : arr){
            if (check != 0) return false;
        }
        return true;
    }
